/**
 * Fresh MongoDB → PostgreSQL migration.
 *
 * SEEDS (upsert, always): betting_houses, deals, settings, provider_accounts, provider_account_houses
 * CLEARS & RE-MIGRATES: everything else from MongoDB (mjmcompany)
 * financial_ledger: cleared but NOT re-migrated (no Mongo source — generated by the app on-demand)
 *
 * Run: npx tsx prisma/migrate-fresh.ts
 */

import { MongoClient, ObjectId } from 'mongodb';
import {
  PrismaClient,
  UserRole,
  UserStatus,
  WithdrawalStatus,
  LinkRequestStatus,
  SyncMode,
} from '@prisma/client';
import { PrismaPg } from '@prisma/adapter-pg';
import { randomUUID } from 'crypto';

function requireEnv(name: string): string {
  const value = process.env[name];
  if (!value) throw new Error(`${name} is required`);
  return value;
}

const MONGO_URI = process.env['MONGO_URI'] ?? '';
if (!MONGO_URI) throw new Error('MONGO_URI is required');
const DATABASE_URL =
  process.env['DATABASE_URL'] ??
  'postgresql://vexxa_user:vexxa_password@localhost:5433/vexxa_db?schema=public';
const adapter = new PrismaPg({ connectionString: DATABASE_URL });
const prisma = new PrismaClient({ adapter });

// ─── ObjectId → UUID mapping ────────────────────────────────────
const idMap = new Map<string, string>();

function mapId(mongoId: string | ObjectId | null | undefined): string | null {
  if (!mongoId) return null;
  const key = mongoId.toString();
  if (!idMap.has(key)) idMap.set(key, randomUUID());
  return idMap.get(key)!;
}

function ensureId(mongoId: string | ObjectId): string {
  return mapId(mongoId)!;
}

function toDate(v: unknown): Date {
  if (v instanceof Date) return v;
  if (typeof v === 'string' || typeof v === 'number') return new Date(v);
  return new Date();
}

function toDecimal(v: unknown): number {
  if (typeof v === 'number') return v;
  if (typeof v === 'string') return parseFloat(v) || 0;
  return 0;
}

// ─── House slug normalization (Mongo aliases → PG canonical slugs) ───
const HOUSE_NORM: Record<string, string> = {
  mjm: 'mgm',
  'bet mgm': 'mgm',
  MJM: 'mgm',
  'BET MGM': 'mgm',
  Superbet: 'superbet',
  Esportivabet: 'esportivabet',
  EsportivaBET: 'esportivabet',
};

function normalizeHouse(raw: string): string {
  const trimmed = raw.trim();
  return HOUSE_NORM[trimmed] ?? trimmed.toLowerCase();
}

// ─── Deal ObjectId → PG UUID mapping (built from slug match) ────
const dealIdMap = new Map<string, string>();

async function buildDealMap(mongo: MongoClient) {
  console.log(
    '\n🔗 Building deal ID map (Mongo ObjectId → PG UUID via slug)...',
  );
  const mongoDeals = await mongo
    .db()
    .collection('deals')
    .find({})
    .project({ _id: 1, bettingHouseSlug: 1 })
    .toArray();
  const pgDeals = await prisma.deal.findMany({
    select: { id: true, bettingHouseSlug: true },
  });
  const pgBySlug = new Map(pgDeals.map((d) => [d.bettingHouseSlug, d.id]));

  for (const md of mongoDeals) {
    const slug = normalizeHouse(md.bettingHouseSlug ?? '');
    const pgId = pgBySlug.get(slug);
    if (pgId) {
      dealIdMap.set(md._id.toString(), pgId);
      console.log(`   ${md._id} (${slug}) → ${pgId}`);
    }
  }
  console.log(`   ✅ ${dealIdMap.size} deals mapped`);
}

function mapDealId(
  mongoId: string | ObjectId | null | undefined,
): string | null {
  if (!mongoId) return null;
  return dealIdMap.get(mongoId.toString()) ?? null;
}

