async function migratePushSubscriptions(mongo: MongoClient) {
  console.log('\n📲 Migrating PushSubscriptions...');
  const docs = await mongo
    .db()
    .collection('pushsubscriptions')
    .find({})
    .toArray();
  let count = 0,
    skipped = 0;
  for (const doc of docs) {
    const userId = mapId(doc.user ?? doc.userId);
    if (!userId) {
      skipped++;
      continue;
    }
    const p256dh = doc.keys?.p256dh ?? doc.p256dh ?? '';
    const auth = doc.keys?.auth ?? doc.auth ?? '';
    if (!doc.endpoint || !p256dh || !auth) {
      skipped++;
      continue;
    }
    try {
      await prisma.pushSubscription.upsert({
        where: { userId_endpoint: { userId, endpoint: doc.endpoint } },
        update: { p256dh, auth },
        create: {
          userId,
          endpoint: doc.endpoint,
          p256dh,
          auth,
          createdAt: toDate(doc.createdAt),
          updatedAt: toDate(doc.updatedAt ?? doc.createdAt),
        },
      });
      count++;
    } catch {
      skipped++;
    }
  }
  console.log(
    `   ✅ ${count}/${docs.length} push subscriptions (${skipped} skipped)`,
  );
}

// ─── Step 13: RankingPrizes → 3 tables ──────────────────────────

async function migrateRankingPrizes(mongo: MongoClient) {
  console.log('\n🏆 Migrating RankingPrizes...');
  const docs = await mongo.db().collection('rankingprizes').find({}).toArray();
  let prizeCount = 0,
    rankCount = 0,
    winnerCount = 0;
  const ptMap: Record<string, string> = {
    balance: 'BALANCE',
    physical: 'PHYSICAL',
    other: 'OTHER',
  };
  const stMap: Record<string, string> = {
    active: 'ACTIVE',
    ended: 'ENDED',
    finalized: 'FINALIZED',
  };
  for (const doc of docs) {
    const id = ensureId(doc._id);
    const createdById = doc.createdBy ? mapId(doc.createdBy) : null;
    if (!createdById) continue;
    const userExists = await prisma.user.findUnique({
      where: { id: createdById },
    });
    if (!userExists) continue;
    try {
      await prisma.rankingPrize.create({
        data: {
          id,
          title: doc.title ?? '',
          description: doc.description ?? '',
          prizeType: (ptMap[(doc.prizeType ?? '').toLowerCase()] ??
            'OTHER') as any,
          prizeValue: toDecimal(doc.prizeValue),
          prizeLabel: doc.prizeLabel ?? '',
          icon: doc.icon ?? '🏆',
          startDate: toDate(doc.startDate),
          endDate: toDate(doc.endDate),
          winnersCount: doc.winnersCount ?? 1,
          targetCpa: doc.targetCpa ?? 0,
          status: (stMap[(doc.status ?? '').toLowerCase()] ?? 'ACTIVE') as any,
          createdById,
          finalizedById: doc.finalizedBy ? mapId(doc.finalizedBy) : null,
          finalizedAt: doc.finalizedAt ? toDate(doc.finalizedAt) : null,
          createdAt: toDate(doc.createdAt),
          updatedAt: toDate(doc.updatedAt ?? doc.createdAt),
        },
      });
      prizeCount++;
    } catch (e: any) {
      console.warn(`   ⚠️ Prize "${doc.title}": ${e.message?.slice(0, 80)}`);
      continue;
    }

    for (const rp of doc.prizes ?? []) {
      try {
        await prisma.rankPrize.create({
          data: {
            rankingPrizeId: id,
            rank: rp.rank,
            prizeType: (ptMap[(rp.prizeType ?? '').toLowerCase()] ??
              'OTHER') as any,
            prizeValue: toDecimal(rp.prizeValue),
            prizeLabel: rp.prizeLabel ?? '',
            icon: rp.icon ?? '',
          },
        });
        rankCount++;
      } catch {
        /* dupe */
      }
    }

    for (const w of doc.winners ?? []) {
      const winnerId = mapId(w.userId);
      if (!winnerId) continue;
      try {
        await prisma.prizeWinner.create({
          data: {
            rankingPrizeId: id,
            userId: winnerId,
            userName: w.userName ?? '',
            campaignId: w.affiliateName ?? '',
            cpaAchieved: w.cpaAchieved ?? 0,
            rank: w.rank ?? 0,
            prizeType: (ptMap[(w.prizeType ?? '').toLowerCase()] ??
              'OTHER') as any,
            prizeValue: toDecimal(w.prizeValue),
            prizeLabel: w.prizeLabel ?? '',
            redeemed: w.redeemed ?? false,
            redeemedAt: w.redeemedAt ? toDate(w.redeemedAt) : null,
            balanceCredited: w.balanceCredited ?? false,
          },
        });
        winnerCount++;
      } catch {
        /* dupe or FK */
      }
    }
  }
  console.log(
    `   ✅ ${prizeCount} prizes | ${rankCount} rank prizes | ${winnerCount} winners`,
  );
}

// ─── Main ───────────────────────────────────────────────────────

async function main() {
  console.log('═'.repeat(60));
  console.log('  FRESH MongoDB → PostgreSQL Migration');
  console.log('  Preserving: betting_houses, deals, settings, providers');
  console.log('═'.repeat(60));

  const mongo = new MongoClient(MONGO_URI);
  await mongo.connect();
  console.log('✅ Connected to MongoDB (mjmcompany)');

  const collections = await mongo.db().listCollections().toArray();
  console.log(
    `Collections: ${collections
      .map((c) => c.name)
      .sort()
      .join(', ')}`,
  );

  try {
    // 1. Seed static tables first (upsert — idempotent)
    await seedBettingHouses();
    await seedDeals();
    await seedSettings();
    await seedProviderAccounts();

    // 2. Build deal ID map (Mongo → PG)
    await buildDealMap(mongo);

    // 3. Clear & re-migrate transactional tables
    await clearTables();

    await migrateUsers(mongo);
    await migrateAffiliateData(mongo);
    await migrateWithdrawals(mongo);
    await migrateNotifications(mongo);
    await migrateCommissionLogs(mongo);
    await migrateLinkRequests(mongo);
    await migrateAuditLogs(mongo);
    await migrateDepositComplianceLogs(mongo);
    await migrateFraudLogs(mongo);
    await migrateSyncLogs(mongo);
    await migrateNotificationSnapshots(mongo);
    await migratePushSubscriptions(mongo);
    await migrateRankingPrizes(mongo);

    console.log('\n' + '═'.repeat(60));
    console.log('  Migration complete!');
    console.log(`  ID mappings: ${idMap.size}`);
    console.log('═'.repeat(60));
  } finally {
    await mongo.close();
    await prisma.$disconnect();
  }
}

main().catch((err) => {
  console.error('Migration failed:', err);
  process.exit(1);
});
